-- Maan World Hospitality (MWH)
-- MySQL 8.x production-ready baseline schema
-- Imported development schema; no production secrets.

SET NAMES utf8mb4;
SET time_zone = '+00:00';
SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE IF NOT EXISTS admin_roles (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, description VARCHAR(255) NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_permissions (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, permission_key VARCHAR(120) NOT NULL UNIQUE, description VARCHAR(255) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_role_permissions (
 role_id BIGINT UNSIGNED NOT NULL, permission_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(role_id,permission_id), CONSTRAINT fk_arp_role FOREIGN KEY(role_id) REFERENCES admin_roles(id) ON DELETE CASCADE, CONSTRAINT fk_arp_permission FOREIGN KEY(permission_id) REFERENCES admin_permissions(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_users (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, role_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'active', last_login_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL, INDEX idx_admin_role_status(role_id,status), CONSTRAINT fk_admin_role FOREIGN KEY(role_id) REFERENCES admin_roles(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS users (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, mobile VARCHAR(20) NOT NULL UNIQUE, email VARCHAR(190) NULL UNIQUE, account_status VARCHAR(30) NOT NULL DEFAULT 'pending_verification', rejection_reason VARCHAR(500) NULL, verified_at TIMESTAMP NULL, verified_by_admin_id BIGINT UNSIGNED NULL, blocked_at TIMESTAMP NULL, blocked_by_admin_id BIGINT UNSIGNED NULL, block_reason VARCHAR(500) NULL, last_login_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL, INDEX idx_users_status(account_status), CONSTRAINT fk_user_verified_admin FOREIGN KEY(verified_by_admin_id) REFERENCES admin_users(id) ON DELETE SET NULL, CONSTRAINT fk_user_blocked_admin FOREIGN KEY(blocked_by_admin_id) REFERENCES admin_users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS otp_codes (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, mobile VARCHAR(20) NOT NULL, purpose VARCHAR(30) NOT NULL, code_hash VARCHAR(255) NOT NULL, expires_at TIMESTAMP NOT NULL, attempts TINYINT UNSIGNED NOT NULL DEFAULT 0, max_attempts TINYINT UNSIGNED NOT NULL DEFAULT 5, verified_at TIMESTAMP NULL, requested_ip VARCHAR(45) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_otp_mobile_purpose_created(mobile,purpose,created_at), INDEX idx_otp_expiry(expires_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS candidate_profiles (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL UNIQUE, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, date_of_birth DATE NULL, gender VARCHAR(30) NULL, full_address VARCHAR(500) NULL, city VARCHAR(100) NULL, country VARCHAR(100) NOT NULL DEFAULT 'India', postcode VARCHAR(20) NULL, referral_code VARCHAR(50) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_candidate_profile_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_candidate_city(city), INDEX idx_candidate_referral(referral_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS professional_details (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL UNIQUE, experience_years DECIMAL(4,1) NOT NULL DEFAULT 0, previous_company_name VARCHAR(190) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_professional_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS categories (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, description VARCHAR(255) NULL, sort_order INT NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS job_roles (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, description VARCHAR(500) NULL, sort_order INT NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL, UNIQUE KEY uq_job_role_category_name(category_id,name), INDEX idx_job_roles_category_active(category_id,is_active), CONSTRAINT fk_job_role_category FOREIGN KEY(category_id) REFERENCES categories(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS job_preferences (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL UNIQUE, category_id BIGINT UNSIGNED NOT NULL, job_role_id BIGINT UNSIGNED NOT NULL, max_travel_distance_km DECIMAL(6,2) NULL, preferred_working_hours DECIMAL(4,1) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_preference_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_preference_category FOREIGN KEY(category_id) REFERENCES categories(id), CONSTRAINT fk_preference_role FOREIGN KEY(job_role_id) REFERENCES job_roles(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS candidate_documents (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, document_type VARCHAR(40) NOT NULL, storage_path VARCHAR(500) NOT NULL, original_file_name VARCHAR(255) NULL, mime_type VARCHAR(100) NULL, file_size_bytes BIGINT UNSIGNED NULL, review_status VARCHAR(30) NOT NULL DEFAULT 'pending', rejection_reason VARCHAR(500) NULL, reviewed_at TIMESTAMP NULL, reviewed_by_admin_id BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL, INDEX idx_documents_user_type(user_id,document_type), INDEX idx_documents_review_status(review_status), CONSTRAINT fk_document_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_document_admin FOREIGN KEY(reviewed_by_admin_id) REFERENCES admin_users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS candidate_payment_profiles (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL UNIQUE, payment_type VARCHAR(20) NOT NULL, account_holder_name VARCHAR(150) NULL, bank_name VARCHAR(150) NULL, account_number_encrypted TEXT NULL, ifsc_code VARCHAR(20) NULL, branch_name VARCHAR(150) NULL, upi_id VARCHAR(190) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_payment_profile_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS hotels (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(190) NOT NULL, description TEXT NULL, address_line VARCHAR(500) NULL, city VARCHAR(100) NULL, state VARCHAR(100) NULL, postcode VARCHAR(20) NULL, country VARCHAR(100) NOT NULL DEFAULT 'India', latitude DECIMAL(10,7) NULL, longitude DECIMAL(10,7) NULL, contact_name VARCHAR(150) NULL, contact_phone VARCHAR(20) NULL, status VARCHAR(30) NOT NULL DEFAULT 'active', created_by_admin_id BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL, INDEX idx_hotels_city_status(city,status), CONSTRAINT fk_hotel_created_admin FOREIGN KEY(created_by_admin_id) REFERENCES admin_users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS hotel_images (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, hotel_id BIGINT UNSIGNED NOT NULL, storage_path VARCHAR(500) NOT NULL, original_file_name VARCHAR(255) NULL, sort_order INT NOT NULL DEFAULT 0, is_primary TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_hotel_images_hotel(hotel_id,sort_order), CONSTRAINT fk_hotel_image_hotel FOREIGN KEY(hotel_id) REFERENCES hotels(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS vacancies (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, hotel_id BIGINT UNSIGNED NOT NULL, category_id BIGINT UNSIGNED NOT NULL, job_role_id BIGINT UNSIGNED NOT NULL, title VARCHAR(190) NOT NULL, description TEXT NULL, openings_count INT UNSIGNED NOT NULL DEFAULT 1, payout_amount DECIMAL(12,2) NOT NULL, payout_period VARCHAR(30) NOT NULL DEFAULT 'per_job', working_hours DECIMAL(4,1) NULL, requirements TEXT NULL, status VARCHAR(30) NOT NULL DEFAULT 'draft', published_at TIMESTAMP NULL, closing_at TIMESTAMP NULL, created_by_admin_id BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL, INDEX idx_vacancy_hotel_status(hotel_id,status), INDEX idx_vacancy_role_status(job_role_id,status), CONSTRAINT fk_vacancy_hotel FOREIGN KEY(hotel_id) REFERENCES hotels(id), CONSTRAINT fk_vacancy_category FOREIGN KEY(category_id) REFERENCES categories(id), CONSTRAINT fk_vacancy_role FOREIGN KEY(job_role_id) REFERENCES job_roles(id), CONSTRAINT fk_vacancy_admin FOREIGN KEY(created_by_admin_id) REFERENCES admin_users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS applications (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, vacancy_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'applied', applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_at TIMESTAMP NULL, reviewed_by_admin_id BIGINT UNSIGNED NULL, rejection_reason VARCHAR(500) NULL, notes TEXT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_application_candidate_vacancy(vacancy_id,user_id), INDEX idx_applications_user_status(user_id,status), INDEX idx_applications_vacancy_status(vacancy_id,status), CONSTRAINT fk_application_vacancy FOREIGN KEY(vacancy_id) REFERENCES vacancies(id), CONSTRAINT fk_application_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT fk_application_admin FOREIGN KEY(reviewed_by_admin_id) REFERENCES admin_users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS jobs (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, application_id BIGINT UNSIGNED NOT NULL UNIQUE, vacancy_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, hotel_id BIGINT UNSIGNED NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'assigned', assigned_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, start_date DATE NULL, end_date DATE NULL, payout_amount DECIMAL(12,2) NOT NULL, assigned_by_admin_id BIGINT UNSIGNED NULL, completed_at TIMESTAMP NULL, notes TEXT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_jobs_user_status(user_id,status), INDEX idx_jobs_hotel_status(hotel_id,status), CONSTRAINT fk_job_application FOREIGN KEY(application_id) REFERENCES applications(id), CONSTRAINT fk_job_vacancy FOREIGN KEY(vacancy_id) REFERENCES vacancies(id), CONSTRAINT fk_job_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT fk_job_hotel FOREIGN KEY(hotel_id) REFERENCES hotels(id), CONSTRAINT fk_job_admin FOREIGN KEY(assigned_by_admin_id) REFERENCES admin_users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS attendance_records (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, job_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, check_in_at TIMESTAMP NOT NULL, check_in_photo_path VARCHAR(500) NOT NULL, check_in_capture_source VARCHAR(20) NOT NULL DEFAULT 'camera', check_in_latitude DECIMAL(10,7) NULL, check_in_longitude DECIMAL(10,7) NULL, check_in_notes VARCHAR(500) NULL, check_out_at TIMESTAMP NULL, check_out_notes VARCHAR(500) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_attendance_job_date(job_id,check_in_at), INDEX idx_attendance_user_date(user_id,check_in_at), CONSTRAINT fk_attendance_job FOREIGN KEY(job_id) REFERENCES jobs(id), CONSTRAINT fk_attendance_user FOREIGN KEY(user_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS payments (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, job_id BIGINT UNSIGNED NULL, amount DECIMAL(12,2) NOT NULL, payment_date DATE NOT NULL, payment_method VARCHAR(30) NOT NULL, transaction_reference VARCHAR(190) NULL, notes VARCHAR(500) NULL, entered_by_admin_id BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_payments_user_date(user_id,payment_date), INDEX idx_payments_job(job_id), UNIQUE KEY uq_payment_reference(transaction_reference), CONSTRAINT fk_payment_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT fk_payment_job FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE SET NULL, CONSTRAINT fk_payment_admin FOREIGN KEY(entered_by_admin_id) REFERENCES admin_users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS notifications (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, admin_user_id BIGINT UNSIGNED NULL, type VARCHAR(50) NOT NULL, title VARCHAR(190) NOT NULL, message TEXT NOT NULL, data_json JSON NULL, read_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_notifications_user_read(user_id,read_at,created_at), INDEX idx_notifications_admin_read(admin_user_id,read_at,created_at), CONSTRAINT fk_notification_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_notification_admin FOREIGN KEY(admin_user_id) REFERENCES admin_users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS support_settings (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, support_phone VARCHAR(30) NULL, support_email VARCHAR(190) NULL, whatsapp_number VARCHAR(30) NULL, instructions TEXT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, updated_by_admin_id BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_support_admin FOREIGN KEY(updated_by_admin_id) REFERENCES admin_users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS audit_logs (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, admin_user_id BIGINT UNSIGNED NULL, user_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(100) NOT NULL, entity_id BIGINT UNSIGNED NULL, old_values JSON NULL, new_values JSON NULL, ip_address VARCHAR(45) NULL, user_agent VARCHAR(500) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_audit_admin_date(admin_user_id,created_at), INDEX idx_audit_entity(entity_type,entity_id,created_at), INDEX idx_audit_user_date(user_id,created_at), CONSTRAINT fk_audit_admin FOREIGN KEY(admin_user_id) REFERENCES admin_users(id) ON DELETE SET NULL, CONSTRAINT fk_audit_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO admin_roles(name,description) SELECT 'Super Admin','Full system access' WHERE NOT EXISTS(SELECT 1 FROM admin_roles WHERE name='Super Admin');
INSERT INTO admin_roles(name,description) SELECT 'Admin','Operational management access' WHERE NOT EXISTS(SELECT 1 FROM admin_roles WHERE name='Admin');
INSERT INTO admin_permissions(permission_key,description) SELECT 'dashboard.view','View dashboard' WHERE NOT EXISTS(SELECT 1 FROM admin_permissions WHERE permission_key='dashboard.view');
INSERT INTO admin_permissions(permission_key,description) SELECT 'candidates.view','View candidates' WHERE NOT EXISTS(SELECT 1 FROM admin_permissions WHERE permission_key='candidates.view');
INSERT INTO admin_permissions(permission_key,description) SELECT 'candidates.verify','Verify/reject candidates' WHERE NOT EXISTS(SELECT 1 FROM admin_permissions WHERE permission_key='candidates.verify');
INSERT INTO admin_permissions(permission_key,description) SELECT 'candidates.block','Block/unblock candidates' WHERE NOT EXISTS(SELECT 1 FROM admin_permissions WHERE permission_key='candidates.block');
INSERT INTO admin_permissions(permission_key,description) SELECT 'hotels.manage','Manage hotels' WHERE NOT EXISTS(SELECT 1 FROM admin_permissions WHERE permission_key='hotels.manage');
INSERT INTO admin_permissions(permission_key,description) SELECT 'vacancies.manage','Manage vacancies' WHERE NOT EXISTS(SELECT 1 FROM admin_permissions WHERE permission_key='vacancies.manage');
INSERT INTO admin_permissions(permission_key,description) SELECT 'applications.manage','Manage applications' WHERE NOT EXISTS(SELECT 1 FROM admin_permissions WHERE permission_key='applications.manage');
INSERT INTO admin_permissions(permission_key,description) SELECT 'jobs.manage','Manage jobs' WHERE NOT EXISTS(SELECT 1 FROM admin_permissions WHERE permission_key='jobs.manage');
INSERT INTO admin_permissions(permission_key,description) SELECT 'attendance.view','View attendance/check-in records' WHERE NOT EXISTS(SELECT 1 FROM admin_permissions WHERE permission_key='attendance.view');
INSERT INTO admin_permissions(permission_key,description) SELECT 'payments.manage','Enter and manage payments' WHERE NOT EXISTS(SELECT 1 FROM admin_permissions WHERE permission_key='payments.manage');
INSERT INTO admin_permissions(permission_key,description) SELECT 'support.manage','Manage support settings' WHERE NOT EXISTS(SELECT 1 FROM admin_permissions WHERE permission_key='support.manage');
INSERT INTO admin_permissions(permission_key,description) SELECT 'audit.view','View audit logs' WHERE NOT EXISTS(SELECT 1 FROM admin_permissions WHERE permission_key='audit.view');
INSERT IGNORE INTO admin_role_permissions(role_id,permission_id) SELECT r.id,p.id FROM admin_roles r CROSS JOIN admin_permissions p WHERE r.name='Super Admin';
SET FOREIGN_KEY_CHECKS = 1;
